// Clipboard stubs belong only to anonymous Actions fixtures; never access a user clipboard.
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {mkdir,mkdtemp,readFile,writeFile,symlink} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join,resolve} from 'node:path';
import {staticOrigin} from './static-origin.mjs';
import {inventory} from '../../scripts/build-pages-artifact.mjs';
assert.equal(process.env.GITHUB_ACTIONS,'true','Use only the authorized Actions runner');
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_PACKAGE);
const artifact=resolve(process.env.PAGES_ARTIFACT),reportDir=resolve(process.env.BROWSER_REPORT);await mkdir(reportDir,{recursive:true});
const git=(...a)=>execFileSync('git',a),sha=b=>createHash('sha256').update(b).digest('hex'),publishedMain='4ab89f3b95350cf8a76ee0aeb7164ea67d16a537';
const report={head:process.env.TESTED_HEAD,base:process.env.TESTED_BASE,publishedMain,checkout:git('rev-parse','HEAD').toString().trim(),files:{},rows:[],mutations:[],external:[],limits:['Only isolated anonymous clipboard stubs on Actions. No real clipboard, mailto or application delivery.','Chromium320/1280; no physical-device, native-speaker or offline certification.','Initial source diagnostic records the published fallback behavior before any repair.']};
assert.equal(report.checkout,report.head);assert.equal(git('rev-parse','HEAD^').toString().trim(),report.base);
for(const {path:p}of inventory(artifact)){const source=p.startsWith('tools/coordinator/')?'coordinator-demo/'+p.split('/').at(-1):p,b=await readFile(join(artifact,p));assert.deepEqual(b,git('show',`${report.head}:${source}`));const publishedExact=b.equals(git('show',`${publishedMain}:${source}`));if(p!=='docs/primserv-roadmap.md')assert(publishedExact,'Diagnostic product input changed: '+p);report.files[p]={source,bytes:b.length,sha256:sha(b),publishedExact};}assert.equal(Object.keys(report.files).length,317);
const expected=["'+FIXTURE =QA X Y | +99912345678 | Telegram","'@FIXTURE",'','30','DO USTALENIA','6 MSC','TAK — -FIXTURE','WSKAŹNIKI: NIE; SZYBKIE TEMPO: NIE','FILMY: NIE; WARUNKI PRACY: NIE','NIE','',''].join('\t');
const serveRoot=await mkdtemp(join(tmpdir(),'primserv-copy-'));await symlink(artifact,join(serveRoot,'kiris-jobs'),'dir');const origin=staticOrigin(serveRoot),base='http://127.0.0.1:4173/kiris-jobs/';let browser;
async function run(width,mode){
 const ctx=await browser.newContext({viewport:{width,height:1000},serviceWorkers:'block',reducedMotion:'reduce'});ctx.setDefaultTimeout(15000);await ctx.route('**/*',r=>{const q=r.request(),u=new URL(q.url());if(!['GET','HEAD'].includes(q.method())){report.mutations.push({method:q.method(),path:u.pathname,blocked:true});return r.abort();}if(u.origin!==new URL(base).origin){report.external.push({host:u.hostname,path:u.pathname,blocked:true});return r.abort();}return r.continue();});
 await ctx.addInitScript(mode=>{
  window.__copyMode=mode;window.__copied=null;window.__copyCalls=[];
  Object.defineProperty(navigator,'clipboard',{configurable:true,get(){return window.__copyMode.startsWith('fallback')?undefined:{writeText:async text=>{window.__copyCalls.push({api:'writeText',text});if(window.__copyMode==='api-denied')throw new DOMException('Anonymous clipboard refusal','NotAllowedError');window.__copied=text;}};}});
  document.execCommand=command=>{const area=document.body.querySelector(':scope > textarea');window.__copyCalls.push({api:'execCommand',command,text:area?.value});if(window.__copyMode==='fallback-throw')throw new DOMException('Anonymous fallback refusal','NotAllowedError');if(window.__copyMode==='fallback-false')return false;window.__copied=area?.value;return true;};
  const data={firstName:'=QA\tX\nY',lastName:'+FIXTURE',phone:'+99912345678',messenger:'telegram',citizenship:'@FIXTURE',gender:'undisclosed',age:'30',location:'any',stayDuration:'six',physicalWork:'yes',physicalDetails:'-FIXTURE',performanceMetrics:'no',fastPace:'no',watchedVideos:'no',understandsRole:'no',longHours:'no',consent:true};localStorage.setItem('citronex_screening_application_v17',JSON.stringify({version:'17.0.0',id:'KAND-COPY-FIXTURE',routeKey:'||||',language:'en',recruiterId:'yana',step:3,data,savedAt:Date.now()}));localStorage.setItem('primserv-copy-unrelated','KEEP');
 },mode);const page=await ctx.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));
 try{
  await page.goto(base+'apply/');await page.locator('[data-action="resume"]').click();await page.locator('[data-action="next"]').click();await page.locator('[data-action="copy"]').waitFor();const before=await page.evaluate(()=>localStorage.getItem('citronex_screening_application_v17')),review=await page.locator('.review-sections').innerText();await page.locator('[data-action="send"]').focus();await page.keyboard.press('Tab');assert.equal(await page.evaluate(()=>document.activeElement.dataset.action),'copy');await page.keyboard.press('Enter');await page.locator('#sendResult:not(.hidden)').waitFor();const observed=await page.evaluate(()=>({notice:document.getElementById('sendResult').textContent,copied:window.__copied,calls:window.__copyCalls,focus:{tag:document.activeElement.tagName,action:document.activeElement.dataset.action||null,opacity:getComputedStyle(document.activeElement).opacity},strayTextareas:document.body.querySelectorAll(':scope > textarea').length}));assert.equal(observed.calls.length,1);assert.equal(observed.calls[0].text,expected);assert.equal(expected.split('\t').length,12);assert.equal(await page.evaluate(()=>localStorage.getItem('citronex_screening_application_v17')),before);assert.equal(await page.locator('.review-sections').innerText(),review);assert.equal(await page.evaluate(()=>localStorage.getItem('primserv-copy-unrelated')),'KEEP');assert.deepEqual(errors,[]);await page.evaluate(()=>document.fonts.ready);await page.locator('.send-box').screenshot({path:join(reportDir,`baseline-copy-${width}-${mode}.png`)});
  const success=['api-success','fallback-true','fallback-false'].includes(mode);assert.equal(observed.notice,success?'The Excel row has been copied.':'The row could not be copied. Open email instead.');if(['api-success','fallback-true'].includes(mode))assert.equal(observed.copied,expected);else assert.equal(observed.copied,null);if(mode==='fallback-false')assert.equal(observed.notice,'The Excel row has been copied.');if(mode==='fallback-throw')assert.equal(observed.strayTextareas,1);
  report.rows.push({width,mode,lang:'en',status:'observed',nativeTabEnter:true,observed,falseSuccess:mode==='fallback-false'&&observed.copied===null&&observed.notice==='The Excel row has been copied.',focusLost:observed.focus.action!=='copy',hiddenTextareaLeaked:observed.strayTextareas>0,answersAndDraftUnchanged:true,unrelatedStoragePreserved:true,noDelivery:true});
 }catch(e){await page.screenshot({path:join(reportDir,`failure-copy-${width}-${mode}.png`)}).catch(()=>{});throw e;}finally{await ctx.close();}
}
try{await origin.start();browser=await chromium.launch({headless:true});report.browser=browser.version();for(const width of [320,1280])for(const mode of ['api-success','api-denied','fallback-true','fallback-false','fallback-throw'])await run(width,mode);assert.equal(report.rows.length,10);assert.equal(report.rows.filter(x=>x.falseSuccess).length,2);assert.equal(report.rows.filter(x=>x.hiddenTextareaLeaked).length,2);assert.deepEqual(report.mutations,[]);assert.deepEqual(report.external,[]);report.applicationDeliveryAttempts=0;report.status='BASELINE_10_COPY_ACTION_MODES_FALSE_SUCCESS_AND_FALLBACK_CLEANUP_OBSERVED';}catch(e){report.status='FAILED';report.failure=e.stack;throw e;}finally{await browser?.close();await origin.stop();report.finished=new Date().toISOString();await writeFile(join(reportDir,'acceptance.json'),JSON.stringify(report,null,2)+'\n');}
